#pragma once
#include <stdint.h>

// 8-bit antialiased glyph (alpha mask), generated by tools/gen_fonts.swift
struct Glyph {
  uint32_t offset;   // into bitmap
  uint8_t  w, h;
  int8_t   xoff;     // left edge relative to pen x
  int8_t   yoff;     // top edge relative to baseline (negative = above)
  uint8_t  advance;
};

struct Font {
  const uint8_t*  bitmap;
  const Glyph*    glyphs;
  const uint16_t* codes;   // sorted code points
  uint16_t        count;
  int16_t         ascent;
  int16_t         descent;
};

extern const Font font_giant;  // Roboto Condensed Bold 116px — digits and "-" only (speed)
extern const Font font_huge;   // Roboto Condensed Bold 92px — digits only
extern const Font font_big;    // Roboto Condensed Bold 50px
extern const Font font_med;    // Roboto Medium 26px
extern const Font font_small;  // Roboto Bold 17px (tracked)
extern const Font font_tiny;   // Roboto Condensed 15px
